"""Summarize workflow tables without writing to the node."""
import argparse
from datetime import datetime, timedelta, timezone
import json
from pathlib import Path
import re


EVERY = re.compile(r"([1-9][0-9]*)([rsmhd])\Z")
CODE = re.compile(r"[+-]?[0-9]+\Z")
SECONDS = {"s": 1, "m": 60, "h": 3600, "d": 86400}
REQUIRED = {
    "routines": ("name", "every", "last_time", "last_code"),
    "schedule": ("name", "at", "claimed"),
}


def reject_constant(value):
    raise ValueError("non-finite JSON number: " + value)


def read_table(node, table):
    try:
        with (node / "wf" / (table + ".json")).open(encoding="utf-8") as stream:
            data = json.load(stream, parse_constant=reject_constant)
    except FileNotFoundError:
        return [], []
    except (OSError, UnicodeError, ValueError):
        return [], [{"table": table, "row": None, "why": "bad_table"}]
    if (not isinstance(data, dict) or data.get("contract") != "wf-table/1"
            or not isinstance(data.get("columns"), list)
            or not all(isinstance(column, str) for column in data["columns"])
            or not isinstance(data.get("rows"), list)):
        return [], [{"table": table, "row": None, "why": "bad_table"}]
    return data["rows"], []


def timestamp(value, now):
    stamp = datetime.fromisoformat(value)
    return stamp if stamp.tzinfo is not None else stamp.replace(tzinfo=now.tzinfo)


def routine(row, now):
    match = EVERY.fullmatch(row["every"])
    if match is None:
        raise ValueError("invalid interval")
    last = timestamp(row["last_time"], now) if row["last_time"] else None
    code_text = row["last_code"]
    if code_text == "":
        code = None
    elif code_text == "running":
        code = "running"
    elif CODE.fullmatch(code_text):
        code = int(code_text)
    else:
        raise ValueError("invalid exit code")
    unit = match.group(2)
    following = (last + timedelta(seconds=int(match.group(1)) * SECONDS[unit])
                 if last is not None and unit != "r" else None)
    if code == "running":
        state = "running"
    elif last is None:
        state = "never"
    elif isinstance(code, int) and code != 0:
        state = "failed"
    elif following is not None and now >= following:
        state = "overdue"
    else:
        state = "ok"
    return {"name": row["name"], "every": row["every"],
            "last_time": row["last_time"] if last is not None else None,
            "last_code": code, "state": state,
            "next": (following.astimezone(timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")
                     if following is not None else None)}


def scheduled(row, now):
    at = timestamp(row["at"], now)
    state = "interrupted" if row["claimed"] else "due" if at <= now else "pending"
    return {"name": row["name"], "at": row["at"], "state": state}


def summarize(node, now):
    result = {"v": 1, "routines": [], "schedule": [],
              "counts": {"routines": dict.fromkeys(
                  ("running", "never", "failed", "overdue", "ok"), 0),
                  "schedule": dict.fromkeys(("interrupted", "due", "pending"), 0)},
              "bad": []}
    for table in ("routines", "schedule"):
        rows, errors = read_table(node, table)
        result["bad"].extend(errors)
        names = set()
        for index, row in enumerate(rows):
            name = row.get("name") if isinstance(row, dict) else None
            if isinstance(name, str) and name and name in names:
                reason = "dup_name"
            else:
                if isinstance(name, str) and name:
                    names.add(name)
                reason = None
                if (not isinstance(row, dict)
                        or not all(isinstance(value, str) for value in row.values())
                        or not all(key in row for key in REQUIRED[table])
                        or not isinstance(name, str) or not name):
                    reason = "bad_row"
                else:
                    try:
                        entry = routine(row, now) if table == "routines" else scheduled(row, now)
                    except (ValueError, OverflowError):
                        reason = "bad_row"
            if reason is not None:
                result["bad"].append({"table": table, "row": index, "why": reason})
            else:
                result[table].append(entry)
                result["counts"][table][entry["state"]] += 1
        result[table].sort(key=lambda entry: entry["name"])
    result["bad"].sort(key=lambda error: (error["table"],
                                           -1 if error["row"] is None else error["row"],
                                           error["why"]))
    return result


def main(argv=None):
    parser = argparse.ArgumentParser(description="Read-only workflow summary")
    parser.add_argument("folder", type=Path)
    parser.add_argument("--now", required=True)
    args = parser.parse_args(argv)
    if not args.folder.is_dir():
        parser.error("folder is not a directory")
    try:
        now = datetime.fromisoformat(args.now)
    except ValueError:
        parser.error("--now must be an ISO timestamp with a timezone")
    if now.tzinfo is None:
        parser.error("--now must have a timezone")
    print(json.dumps(summarize(args.folder, now), ensure_ascii=False, separators=(",", ":")))
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
